import{at as e,it as t,n,vt as r}from"./chunks/framework.BmH7hI6Z.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}`),a={name:`guide/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>Soukai is an <a href="https://en.wikipedia.org/wiki/Active_record_pattern" target="_blank" rel="noreferrer">Active Record</a> library made for the <a href="./solid-protocol/what-is-solid.html">Solid Protocol</a>.</p><p>Here are some of the main reasons to use it:</p><ul><li><strong>RDF made easy:</strong> Define your own data shapes using <a href="https://zod.dev/" target="_blank" rel="noreferrer">Zod</a> with <a href="./core-concepts/models.html">model schemas</a>, and decide how fields are mapped into RDF properties. No need to fiddle with RDF!</li><li><strong>Decouple logic from storage:</strong> Write code that is independent from storage, and use different <a href="./core-concepts/engines.html">engines</a> at runtime to configure how the data is persisted: in memory, in the browser storage, or in a Solid POD.</li><li><strong>Framework agnostic:</strong> Soukai is written in pure JavaScript, you&#39;ll be able to use it with your favorite framework (it also works in the backend!).</li><li><strong>Built on standards:</strong> With the Solid Protocol at its core, it also supports other specifications from the ecosystem; such as <a href="./advanced/interoperability.html#type-indexes">Type Indexes for interoperability</a>, or <a href="./advanced/authorization.html">WAC/ACP for managing permissions</a>.</li><li><strong>Local-first:</strong> History tracking and conflict resolution are built right into the library with <a href="./advanced/local-first.html">a CRDT tailored to the Solid Protocol</a>.</li></ul>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};